package com.smarthub.plus;
import android.app.*;import android.content.*;import android.os.Bundle;import java.net.*;import java.nio.charset.StandardCharsets;import org.json.*;
/** Normal application UID, read-only SDK request; never tunes or registers a replacement listener. */
final class ReceiverSignalProbe24 {
 static void production(Context c,Bundle result)throws Exception{SatelliteState state=SatelliteState.read(c);result.putInt("normal_app_uid",android.os.Process.myUid());long first=0;try(DirectReceiverSignal reader=new DirectReceiverSignal(c)){for(int n=0;n<14;n++){reader.refresh(state);Thread.sleep(1000);long seen=DirectReceiverSignal.timestamp(state);if(first==0&&seen>0)first=seen;}for(String field:new String[]{"strength","quality","snr","ber"})result.putString(field,ReceptionData.value(c,state,field));result.putString("format",DirectReceiverSignal.format(state));result.putLong("successful_live_reads",reader.successes());result.putBoolean("readings_refreshed",DirectReceiverSignal.timestamp(state)>first&&first>0);result.putBoolean("native_info_visible",c.getSharedPreferences("smarthub",0).getBoolean("satellite_native_banner_visible",false));SatelliteState other=state.copy();other.channelId+="-test-other";result.putBoolean("other_channel_rejected",ReceptionData.value(c,other,"strength").isEmpty());if(reader.successes()<2||ReceptionData.value(c,state,"strength").isEmpty())throw new java.io.IOException("Production direct measurements unavailable");}result.putBoolean("closed_reader_has_no_stale_data",!DirectReceiverSignal.live(state));}
 static void run(Context c,Bundle result)throws Exception{result.putInt("normal_app_uid",android.os.Process.myUid());result.putString("request","Tuner/0003");try(DatagramSocket socket=new DatagramSocket()){socket.setSoTimeout(600);byte[] request="Tuner\n0003\n{\"iTunerIndex\":0}".getBytes(StandardCharsets.UTF_8);socket.send(new DatagramPacket(request,request.length,InetAddress.getByName("127.0.0.1"),51021));long until=android.os.SystemClock.elapsedRealtime()+4500;int count=0;boolean found=false;while(android.os.SystemClock.elapsedRealtime()<until){byte[] b=new byte[65507];DatagramPacket p=new DatagramPacket(b,b.length);try{socket.receive(p);}catch(SocketTimeoutException wait){continue;}if(!p.getAddress().isLoopbackAddress())continue;count++;String[] fields=new String(p.getData(),p.getOffset(),p.getLength(),StandardCharsets.UTF_8).split("\n",3);if(fields.length<3||!fields[0].equalsIgnoreCase("Tuner")||!fields[1].equals("0003"))continue;result.putString("reply_mark",fields[2].startsWith("SUCCESS:")?"SUCCESS":"OTHER");int start=fields[2].indexOf('{');if(start<0)continue;JSONObject j=new JSONObject(fields[2].substring(start).replace("\u0000",""));for(String k:new String[]{"bLocked","iTpId","iTunerIndex","iSignalStrength","iSignalQuality","iSigSNR","iSigBER","signalFormat"})if(j.has(k))result.putString(k,j.optString(k));found=j.has("iSignalStrength");result.putInt("reply_source_port",p.getPort());if(found)break;}result.putInt("packets",count);result.putBoolean("direct_reply",found);}}
 static void restore(Instrumentation test,Context c,Bundle result)throws Exception{Activity activity=test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));test.runOnMainSync(()->activity.startForegroundService(new Intent(activity,SatelliteCompanionService.class).setAction("com.smarthub.plus.satellite.START")));test.waitForIdleSync();c.startActivity(new Intent("android.intent.action.home").setPackage("com.tosmart.aurum").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(3500);result.putBoolean("service_signal_live",DirectReceiverSignal.live(SatelliteState.read(c)));result.putString("service_strength",ReceptionData.value(c,SatelliteState.read(c),"strength"));result.putString("service_snr",ReceptionData.value(c,SatelliteState.read(c),"snr"));result.putBoolean("can_draw",android.provider.Settings.canDrawOverlays(c));result.putBoolean("companion_running",c.getSharedPreferences("smarthub",0).getBoolean("satellite_companion_running",false));}
}
